import pandas as pd


def clean_records(records):
    if len(records) == 0:
        return []
    df = pd.DataFrame(records)
    ages = pd.to_numeric(df["age"], errors="coerce")
    median = ages.median()
    if pd.isna(median):
        median = 0.0
    df["age"] = ages.fillna(median).astype(float).round(2)
    df = df.dropna(subset=["email"])
    return df.to_dict(orient="records")
